SpellData={
["17"]={"味方にシールドを張りし、$N2ダメージを\n吸収します。$N1秒間持続します。\nシールドが維持される間は、\nダメージによるspell詠唱の妨害は\n起こりません。",nil,"$N1ダメージ吸収。"},
["53"]={"ターゲットを背後から攻撃し、$N1 ダメージを与えます。\n対象の前にいてはなりません。\n1コンボポイントを得ます。",nil,""},
["66"]={"術者は$N1秒間に徐々に不可視と\nなり、毎秒Thraetが減少します。\nあらゆる行動により効果が解除されます。\n$N2秒間持続します。",nil,"姿を消している。３秒間持続。"},
["71"]={"防御の構え。\n受けるダメージを$N1%減少します。\n攻撃によるThreatの生成が増加し、\nさらに$N3秒間に$N2Rage生成されます。\n(Lelev 92+)\narmorがさらに10%上昇します。",nil,"防御力アップ"},
["81"]={"敵の近接攻撃(melee)を回避する\nチャンスを与えます。",nil,""},
["99"]={"咆哮し、$N2秒間、$N1ヤード以内の敵\n全員を混乱させます。\nダメージを与えると効果がなくなります。\n全てのフォームで使えます。",nil,"混乱させる。"},
["100"]={"敵に突撃し、Rageを$N2生成し、\n$N2秒間移動させません(root)。",nil,""},
["116"]={"敵に冷気の矢を放ち、$N1Frostダメージを\n与え、$N3秒間、移動速度を$N2%遅くします。\n\n",nil,"移動速度が$N1%低下。\n$N2秒間持続。\n"},
["118"]={"敵を羊に変身させ、$N1秒間、その\n辺りを歩き回らせます。その間、敵は\n攻撃も魔法詠唱も出来ませんが、\n急速に回復します。ダメージを与えると\n効果は中断されます。$N2体のみ作用し、\nBeast、Humanoid、Critterにのみ有効です。\n\nGlyph of Crittermorph：\nCritterに対しては、複数の対象に作用し、\n$N3日の効果時間を持ちます。",nil,"攻撃と魔法の詠唱ができない。\n回復力上昇。"},
["120"]={"術者の前方扇形の範囲にいる対象に\n$N1のFrostダメージを与え、$N3秒間\n移動速度を$N2%低下させます。",nil,"移動速度が$N1%低下。6秒間持続。"},
["122"]={"術者から$N1ヤード以内の敵に$N2の\nFrost属性ダメージを与え、$N3秒間\n凍り付かせてその場から動けなくします。\nダメージを与えると効果が切れることが\nあります。",nil,"凍りついて動けない。"},
["130"]={"対象のグループメンバーの落下速度を\n$N1秒間遅くします。",nil,"ゆっくり落下する。"},
["133"]={"火の玉を投げつけ、$N1Fire\nダメージを与えます。",nil,""},
["136"]={"$N2秒間にペットの総healthの\n$N1%を回復します。",nil,"$N2秒毎にペットのHealthの$N1%を回復。\n$N3秒間持続"},
["139"]={"瞬時に$N1回復したあと、\n$N3秒間に$N2回復します。",nil,"$N2秒毎にHealthを$N1回復。"},
["172"]={"$N2秒間に渡って、対象にShadow属性の$N1ダメージを\n与えます。",nil,""},
}
